module freq_diveven(
    input clk, rst_n,
    output clk_div
);
    parameter NUM_DIV = 6;

    reg [3:0] cnt;
    reg clk_div_reg;
    assign clk_div = clk_div_reg;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            cnt <= 0;
            clk_div_reg <= 0;
        end
        else begin
            if(cnt < (NUM_DIV/2 - 1))
                cnt <= cnt + 1;
            else begin
                cnt <= 0;
                clk_div_reg <= ~clk_div_reg;
            end
        end
    end

endmodule
